TLM.f("Sancti/06-24",{"officium":"In Nativitate S. Joannis Baptistæ","rule":["Gloria","Credo","Prefatio=Baptista"],"sections":{"Introitus":[{"k":"ref","la":"Isa 49:1; 49:2"},{"k":"text","la":"De ventre matris meæ vocávit me Dóminus in nómine meo: et pósuit os meum ut gládium acútum: sub teguménto manus suæ protéxit me, et pósuit me quasi sagíttam eléctam."},{"k":"ref","la":"Ps 91:2"},{"k":"text","la":"Bonum est confitéri Dómino: et psállere nómini tuo, Altíssime."},{"k":"macro","name":"Gloria"},{"k":"text","la":"De ventre matris meæ vocávit me Dóminus in nómine meo: et pósuit os meum ut gládium acútum: sub teguménto manus suæ protéxit me, et pósuit me quasi sagíttam eléctam."}],"Oratio":[{"k":"text","la":"Deus, qui præséntem diem honorábilem nobis in beáti Joánnis nativitáte fecísti: da pópulis tuis spirituálium grátiam gaudiórum; et ómnium fidélium mentes dirige in viam salútis ætérnæ."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Isaíæ Prophétæ"},{"k":"ref","la":"Isa 49:1-3; 49:5-7"},{"k":"text","la":"Audíte, ínsulæ, et atténdite, pópuli, de longe: Dóminus ab útero vocavit me, de ventre matris meæ recordátus est nóminis mei. Et pósuit os meum quasi gládium acútum: in umbra manus suæ protéxit me, et pósuit me sicut sagíttam eléctam: in pháretra sua abscóndit me. Et dixit mihi: Servus meus es tu, Israël, quia in te gloriábor. Et nunc dicit Dóminus, formans me ex útero servum sibi: Ecce, dedi te in lucem géntium, ut sis salus mea usque ad extrémum terræ. Reges vidébunt, et consúrgent príncipes, et adorábunt propter Dominum et sanctum Israël, qui elégit te."}],"Graduale":[{"k":"ref","la":"Jer 1:5; 1:9"},{"k":"text","la":"Priusquam te formárem in útero, novi te: et ántequam exíres de ventre, sanctificávi te."},{"k":"text","la":"Misit Dóminus manum suam, et tétigit os meum, et dixit mihi.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Luc 1:76"},{"k":"text","la":"Tu, puer, Prophéta Altíssimi vocáberis: præíbis ante Dóminum paráre vias ejus. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Luc 1:76"},{"k":"text","la":"Tu, puer, Propheta Altíssimi vocáberis: præíbis ante Dóminum paráre vias ejus. Allelúja."},{"k":"ref","la":"Hos 14:6"},{"k":"text","la":"Justus germinábit sicut lílium, et florébit in ætérnum ante Dóminum. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 1:57-68"},{"k":"text","la":"Elísabeth implétum est tempus pariéndi, et péperit fílium. Et audiérunt vicíni et cognáti ejus, quia magnificávit Dóminus misericórdiam suam cum illa, et congratulabántur ei. Et factum est in die octávo, venérunt circumcídere púerum, et vocábant eum nómine patris sui Zacharíam. Et respóndens mater ejus, dixit: Nequáquam, sed vocábitur Joánnes. Et dixérunt ad illam: Quia nemo est in cognatióne tua, qui vocétur hoc nómine. Innuébant autem patri ejus, quem vellet vocári eum. Et póstulans pugillárem, scripsit, dicens: Joánnes est nomen ejus. Et miráti sunt univérsi. Apértum est autem illico os ejus et lingua ejus, et loquebátur benedícens Deum. Et factus est timor super omnes vicínos eórum: et super ómnia montána Judææ divulgabántur ómnia verba hæc: et posuérunt omnes, qui audíerant in corde suo, dicéntes: Quis, putas, puer iste erit? Etenim manus Dómini erat cum illo. Et Zacharías, pater ejus, repletus est Spíritu Sancto, et prophetávit, dicens: Benedíctus Dóminus, Deus Israël, quia visitávit et fecit redemptiónem plebis suæ."}],"Offertorium":[{"k":"ref","la":"Ps 91:13"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus, quæ in Líbano est, multiplicábitur. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Tua, Dómine, munéribus altária cumulámus: illíus nativitátem honóre débito celebrántes, qui Salvatórem mundi et cécinit ad futúrum et adésse monstravit, Dóminum nostrum Jesum Christum, Fílium tuum:"},{"k":"macro","name":"Qui tecum"}],"Communio":[{"k":"ref","la":"Luc 1:76"},{"k":"text","la":"Tu, puer, Propheta Altíssimi vocaberis: præíbis enim ante fáciem Dómini paráre vias ejus."}],"Postcommunio":[{"k":"text","la":"Sumat Ecclésia tua, Deus, beáti Joánnis Baptístæ generatióne lætítiam: per quem suæ regeneratiónis cognóvit auctórem, Dóminum nostrum Jesum Christum, Fílium tuum:"},{"k":"macro","name":"Qui tecum"}]},"hr":{"ca25c0fa08d0139d":{"t":"Iz 49, 1 i 2, Ps 91, 2\n(Iz 49, 1 i 2) Iz utrobe moje majke pozvao me je Gospodin po imenu; učinio je moja usta kao oštar mač. Zaštitio me je okriljem svoje ruke i učinio me izabranom strijelom. (Ps 91, 2) Dobro je slaviti Gospodina, i pjevati imenu tvojemu, Svevišnji.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Iz 49, 1 i 2) Iz utrobe moje majke pozvao me je Gospodin po imenu; učinio je moja usta kao oštar mač. Zaštitio me je okriljem svoje ruke i učinio me izabranom strijelom.","v":"∅ → in; ∅ → in","kn":"(Isai. 49, 1). Od utrobe majke moje prozva me imenom mojim i učini usta moja kao oštar mač. u sjenu ruke svoje sakri me i učini me strijelom izabranom, (Ps. 91, 2). Dobro je slaviti Goejppdina i pjevati imenu Tvomu. Višnji! Slava Ocu . . . Od utrobe ...","knRef":"Kniewald 1942, str. 606–607 (snimka 304) (OCR)"},"ea09bc542c71244a":{"t":"<i>Pomolimo se</i>.\nBože, koji si nam današnji dan učinio časnim po rođenju blaženoga Ivana, daj svome puku milost duhovnih radosti, a duše svih vjernika upravljaj na put vječnoga spasenja.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si nam današnji dan učinio narodima T ^ duše svih svojih vjernih putem vječnoga spasenje, po G. n. ^","knRef":"Kniewald 1942, str. 608–609 (snimka 305) (OCR)"},"1ca3207c35be0627":{"t":"Isai 49, 1-3, 5, 6 i 7\nČitanje Izaije proroka. Čujte, morem opkoljeni krajevi, poslušajte vi. daleki narodi: Iz utrobe moje majke pozvao me je Gospodin po imenu; učinio je moja usta kao oštar mač, štitio me je svojom rukom, izgladio me kao strelicu i sakrio me u svoj tobolac. I reče mi; Ti si, Izraele, sluga moj i po tebi ću se proslaviti. I Gospodin koji me iz krila majke uze. za svojega slugu, govori mi sada: Eto, postavio sam te za svjetlo narodima, da naviještaš moj spas do nakraj zemlje. Kraljevi će vidjeti, knezovi će ustati, da se poklone Gospodinu i Svecu Izraelovu koji te je izabrao.","kn":"Čitanje proroka Izalje (49, 1-3. 5-7). Čujte otoci I Poslufejte narodi, Izdaleka: Gospodin me ’je pozvao od rođenja 1 Jz krila me majčina prozvao mač, Štitio me sjenom svoje ruke, stavio meje kao izabranu strijellcu i sakrio me u svoj tobo! ac. I reče mi: Ti si, Izraele, moj sluga 1 po tebi tin ^ °°®P°din. koji me je od maj- Cina krila učinio svojim slugom, sada ml govori- svijetlo narodirna da zemlje. Kraljevi će vidjeti i knezovi će ustati, da se klanjaju radi Go- ■ spođina i Sveca Izraelova, koji te je Izabrao.","knRef":"Kniewald 1942, str. 608–609 (snimka 305) (OCR)"},"a5f66d9e7fd51831":{"t":"Jr 1, 5 i 9\nPrije nego sam te oblikovao u majčinoj utrobi, poznao sam te, i prije nego si izašao iz: krila, posvetio sam te. Gospodin je pružio svoju ruku, dotakao se mojih usta i govorio je meni.\n\nLk 1, 76\n<i>Aleluja</i>, <i>aleluja</i>.\nTi, dijete, zvat ćeš se prorok Svevišnjega, ići ćeš pred Gospodinom da mu pripraviš putove. <i>Aleluja</i>."},"ec749e1953194484":{"t":"Lk 1, 57-68\nSlijedi sveto Evanđelje po Luki. Elizabeti se navrši vrijeme i rodi sina. Kad njezini susjedi i rodbina doznaše, da joj je Gospodin iskazao veliko milosrđe, radovahu se s njom. Osmoga dana dođu da obrežu dijete i htjeli su ga nazvati imenom njegova oca Zaharije. Ali njegova majka reče: Ne tako, nego zvat će se Ivan! Odvrate joj: Nitko se od tvojega roda ne zove tako. Znakovima upitaju njegova oca, kako bi on htio da se zove. On zatraži pločicu i napisa: Ivan mu je ime. Svi se začude tome, a njemu se istog časa otvore usta i razriješi jezik, te je govorio i hvalio Boga. Nato sve susjede spopadne strah, i ovo se razglasi po svim judejskim gorama. Svi koji su to čuli, pohranjivali su u svom srcu i govorili: Što misliš, što će biti ovo dijete? I ruka je Gospodnja bila s njime. A njegov otac Zaharija napuni se Duha Svetoga i prorokova: Blagoslovljen Gospodin Bog Izraelov, jer pohodi i otkupi narod svoj!"},"26bc9b7e0a4c66c8":{"t":"Ps 91, 13\nPravednik cvate kao palma i raste kao libanski cedar.","kn":"(Ps. 91, 13). Pravednik cvate poput paome i raste poput libanskog cedra.","knRef":"Kniewald 1942, str. 608–609 (snimka 305) (OCR)"},"e5da35510020fd12":{"t":"Tvoje žrtvenike, Gospodine, napunjamo žrtvenim darovima slaveći zasluženom čašću rođenje onoga koji je i predskazao i pokazao Spasitelja svijeta, Gospodina našega Isusa Krista, Sina tvoga:\n<i>koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Napon jamo darovima Gospodine, Tvoje žrtvenike, dužnom čašću slaveći rođenje onoga, 4coji je i prorekao, da. će doći Spasitelj svijeta i pokazao nazočna. Gospodina našega, Isusa. Krista, koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga...","knRef":"Kniewald 1942, str. 608–609 (snimka 305) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"584dbaeced390f16":{"t":"Lk 1, 76\nTi, dijete, zvat ćeš se prorok Svevišnjega, ići ćeš pred Gospodinom da mu pripraviš putove.","kn":"(Lk. 1). Ti dijete, zvat ćeš se prorok Višnjega; jer ćeš ići pred licem Gospodnjim, da pripraviš putove njegove.","knRef":"Kniewald 1942, str. 608–609 (snimka 305) (OCR)"},"6a783385a5256217":{"t":"<i>Pomolimo se</i>.\nNeka se tvoja Crkva, Gospodine, razveseli o rođenju blaženog Ivana Krstitelja, po kojem je upoznala začetnika svoga preporođenja, Gospodina našega Isusa Krista, Sina tvoga:\n<i>koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primila Tvoja Crkva, Gospodine Bože, radost od rođenja Svetog Ivana Krstitelja, po kome je spoznala začetnika svoga preporođenja. Gospodina našega, Isusa Kriste, Sina Tvoga, koji s Tobom živi i kraljuje...","knRef":"Kniewald 1942, str. 608–609 (snimka 305) (OCR)"},"adad0f7f2fcbfa9b":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi. Gospodine, sveti Oče, svemogući vječni Bože. – Ti si s jedinorođenim Sinom tvojim i s Duhom Svetim jedan Bog, jedan Gospodin, ne u jedinstvu jedne osobe, već u Trojstvu jedine biti. Što naime po tvojoj objavi vjerujemo o tvojoj slavi, to isto bez razlike i razlučivanja vjerujemo i o tvome Sinu i o Duhu Svetome. Tako se u ispovijedanju istinitog i vjekovječnog božanstva klanjamo i vlastitosti osoba i jedinstvu biti i jednakosti veličanstva. – Koje hvale anđeli i arkanđeli, kerubini i serafini koji ne prestaju svaki dan klicati govoreći složnim glasom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Go. spodine sveti, Oće svemogući, vječni Bože, koji si sa Sinom svojim i s Duhom Svetim jedan Bog i je- dan Gospodin: ne u jedinstvu osobe, nego u Trojstvu jedne biti. Jer sve, što po Tvojem otkrivenju vjerujemo o Tvojoj slavi, to bez razlike i razlučivanja mislimo i o Sinu Tvoj emu i o Duhu Svetomu. Ispovijedajući pravo i vječno Božanstvo, klanjamo se tako i vlastitosti u osobama i jedinstvu u biti i jednakosti u veličanstvu, koje hvale anđeli i arkanđeli, kerubini i serafini, koji ne prestaju klicati svakog dana jednoglasno govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"}}});
